//! Validates the generated Kubernetes `MatchConfig` presets.
//!
//! The presets in `src/kubernetes.rs` are generated by `cargo xtask generate`.
//! These tests pin the key behaviour (composite keys, distinguished keys) and,
//! by referencing the module, confirm the generated tree compiles under the
//! `kubernetes` feature.
#![cfg(feature = "kubernetes")]

use cool_diff::ArrayMatchMode;
use cool_diff::kubernetes::core;

/// Asserts the config at `path` is a key match over exactly `keys`.
#[track_caller]
fn assert_keys(config: &cool_diff::MatchConfig, path: &str, keys: &[&str]) {
    let mode = config
        .config_at(path)
        .unwrap_or_else(|| panic!("no config at `{path}`"))
        .mode();
    match mode {
        ArrayMatchMode::Key(actual) => assert_eq!(actual, keys, "wrong keys at `{path}`"),
        other => panic!("expected a key match at `{path}`, got {other:?}"),
    }
}

#[test]
fn pod_container_ports_use_composite_key() {
    let config = core::v1::pod();
    assert_keys(&config, "spec.containers", &["name"]);
    assert_keys(
        &config,
        "spec.containers.ports",
        &["containerPort", "protocol"],
    );
    assert_keys(&config, "spec.volumes", &["name"]);
}

#[test]
fn service_ports_use_composite_key() {
    let config = core::v1::service();
    assert_keys(&config, "spec.ports", &["port", "protocol"]);
}

#[test]
fn config_map_carries_object_meta() {
    // Every kind embeds ObjectMeta, so its annotated arrays appear even on a
    // simple resource like ConfigMap.
    let config = core::v1::config_map();
    assert_keys(&config, "metadata.ownerReferences", &["uid"]);
}
